<?php
class Reporte_vehiculo extends CI_Controller{
 private $session_data=array();
 public function __construct(){parent::__construct();if(!$this->session->userdata('logged_in'))redirect('','refresh');$this->session_data=$this->session->userdata('logged_in');$this->load->model('Reporte_vehiculo_model');$this->load->model('Sistema_model');$this->load->model('Parametro_model');if(!$this->Reporte_vehiculo_model->usuario_tiene_rol((int)$this->session_data['usuario_id'],220))show_error('No tiene permiso para generar reportes de Transporte.',403,'Acceso denegado');}
 private function filtros(){ $d=trim((string)$this->input->get('desde',true));$h=trim((string)$this->input->get('hasta',true));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d))$d=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$h))$h=date('Y-m-d');if($d>$h){$x=$d;$d=$h;$h=$x;}return array('desde'=>$d,'hasta'=>$h,'vehiculo_id'=>(int)$this->input->get('vehiculo_id',true));}
 public function index(){ $f=$this->filtros();$p=$this->Parametro_model->get_parametros();$data['sistema']=$this->Sistema_model->get_sistema();$data['parametro']=isset($p[0])?$p[0]:$p;$data['filtros']=$f;$data['vehiculos']=$this->Reporte_vehiculo_model->vehiculos();$data['filas']=$this->Reporte_vehiculo_model->reporte($f);$data['tiene_km']=$this->Reporte_vehiculo_model->tiene_km();$data['page_title']='Reporte por vehículo';$data['_view']='reporte_transporte/vehiculo';$this->load->view('layouts/main',$data);}
 public function csv(){ $f=$this->filtros();$rs=$this->Reporte_vehiculo_model->reporte($f);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="reporte_vehiculos_'.$f['desde'].'_'.$f['hasta'].'.csv"');echo "\xEF\xBB\xBF";$x=fopen('php://output','w');fputcsv($x,array('Vehiculo','Viajes realizados','Pasajeros transportados','Kilometros','Ingresos','Ocupacion promedio %','Cancelaciones'),';');foreach($rs as $r)fputcsv($x,array($r['vehiculo'],$r['viajes_realizados'],$r['pasajeros'],$r['kilometros'],number_format($r['ingresos'],2,'.',''),number_format($r['ocupacion'],2,'.',''),$r['cancelaciones']),';');fclose($x);exit;}
}
